def evaluate(expr: str) -> int:
    import re

    # Tokenize the expression
    tokens = re.findall(r'\d+|[()+\-*/]', expr)

    # Convert tokens to a list of numbers and operators
    # We'll use a recursive descent parser
    pos = [0]  # Use a list to allow modification in nested functions

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        token = tokens[pos[0]]
        pos[0] += 1
        return token

    def parse_expression():
        # expression = term (('+' | '-') term)*
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        # term = factor (('*' | '/') factor)*
        result = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                # Integer division truncating toward zero
                # Python's // truncates toward negative infinity, so we need to handle this
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Truncate toward zero
                quotient = result / right
                result = int(quotient)
        return result

    def parse_factor():
        # factor = ('+' | '-') factor | '(' expression ')' | number
        token = peek()
        if token == '+':
            consume()
            return parse_factor()
        elif token == '-':
            consume()
            return -parse_factor()
        elif token == '(':
            consume()  # consume '('
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            consume()  # consume ')'
            return result
        elif token is not None and token.isdigit():
            consume()
            return int(token)
        else:
            raise ValueError(f"Unexpected token: {token}")

    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected token after expression")
    return result
