def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]

    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digits(num: int) -> str:
        if num < 20:
            return ones[num]
        t = num // 10
        o = num % 10
        if o == 0:
            return tens[t]
        return tens[t] + "-" + ones[o]

    def three_digits(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 100:
            parts.append(ones[num // 100] + " hundred")
            num %= 100
        if num > 0:
            parts.append(two_digits(num))
        return " ".join(parts)

    result = []

    # Handle millions
    if n >= 1_000_000:
        millions = n // 1_000_000
        result.append(three_digits(millions) + " million")
        n %= 1_000_000

    # Handle thousands
    if n >= 1_000:
        thousands = n // 1_000
        result.append(three_digits(thousands) + " thousand")
        n %= 1_000

    # Handle remaining
    if n > 0:
        result.append(three_digits(n))

    return " ".join(result)
