def flatten_json(obj: dict) -> dict:
    """
    Flatten a nested dictionary and lists into a single-level dictionary.

    Args:
        obj: A dictionary that may contain nested dictionaries and lists.

    Returns:
        A flattened dictionary where keys are dot-separated paths.
    """
    result = {}

    def _flatten(current_obj, prefix=""):
        if isinstance(current_obj, dict):
            if not current_obj:
                # Empty dict is kept as a leaf value
                if prefix:
                    result[prefix] = current_obj
                return
            for key, value in current_obj.items():
                new_key = f"{prefix}.{key}" if prefix else key
                _flatten(value, new_key)
        elif isinstance(current_obj, list):
            if not current_obj:
                # Empty list is kept as a leaf value
                if prefix:
                    result[prefix] = current_obj
                return
            for index, value in enumerate(current_obj):
                new_key = f"{prefix}.{index}" if prefix else str(index)
                _flatten(value, new_key)
        else:
            # Leaf value (number, string, boolean, None, etc.)
            if prefix:
                result[prefix] = current_obj

    _flatten(obj)
    return result
