def parse_csv_line(line: str) -> list[str]:
    fields = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check if next char is also a quote (escaped quote)
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 1  # Skip the next quote
                else:
                    # End of quoted field
                    in_quotes = False
            else:
                current.append(char)
        else:
            if char == '"':
                # Start of quoted field
                in_quotes = True
            elif char == ',':
                # End of field
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)

        i += 1

    # Add the last field
    fields.append(''.join(current))

    return fields
